package com.mohymods.kingdomsmp.profession;
import com.mohymods.kingdomsmp.building.*;
import com.mohymods.kingdomsmp.economy.*;
import com.mohymods.kingdomsmp.persistence.*;
import com.mohymods.kingdomsmp.placement.PlacementProtection;
import com.mojang.brigadier.arguments.StringArgumentType;
import java.io.IOException;
import java.util.*;
import net.minecraft.commands.*;
import net.minecraft.commands.arguments.*;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.chat.*;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.Block;
import net.neoforged.fml.ModList;
/** Human source/catalogue inspection and permanent native inventory delivery in one canonical receipt. */
public final class LibraryGlyphCatalogueService {
 private record Quote(UUID nonce,UUID player,String quest,long revision,long issued,String snapshot,String reason,List<ItemStack> before,List<ItemStack> after,List<CompoundTag> items,List<CompoundTag> facts){
  Quote{before=before.stream().map(ItemStack::copy).toList();after=after.stream().map(ItemStack::copy).toList();items=items.stream().map(CompoundTag::copy).toList();facts=facts.stream().map(CompoundTag::copy).toList();}
 }
 private static final Map<ServerPlayer,Quote> REVIEWS=new WeakHashMap<>();
 private LibraryGlyphCatalogueService(){}
 public static boolean supported(){return ModList.get().getModContainerById("ars_nouveau").map(v->v.getModInfo().getVersion().toString().equals("5.13.3")).orElse(false);}
 public static String status(){return status(LibraryGlyphCatalogue.QUEST);}
 public static String status(String quest){if(quest.equals(LibraryGlyphCatalogue.MASTER))return "ALPHA TIER 6: inspect and permanently deliver six different native Tier 2 glyphs. The original Tier 3 archive remains reserved for a future update. Requires all sixteen earlier objectives and current Library/source inspection.";if(quest.equals(LibrarySpellCatalogue.MASTER))return "ALPHA TIER 6: inspect and permanently deliver six different native RARE spell IDs. The original EPIC archive remains reserved for a future update. Current native components/rarity and all sixteen earlier objectives are required.";if(LibrarySpellCatalogue.isSpellQuest(quest))return "Requires Iron's Spells 3.16.3. Bring four different native RARE spell IDs to the Library. An on-site operator inspects their legitimate source and catalogue, then confirms permanent delivery for 200 XP. Generic item rarity and copied tags do not count.";return "Bring four different native Tier 2 Ars glyphs to the Library. An on-site operator inspects their legitimate source and research catalogue, then confirms permanent delivery for 200 XP. Requires verified Ars Nouveau 5.13.3.";}
 public static boolean eligible(ServerPlayer p){return eligible(p,LibraryGlyphCatalogue.QUEST);}
 public static boolean eligible(ServerPlayer p,String quest){if(!(LibrarySpellCatalogue.isSpellQuest(quest)?NativeLibraryScroll.supported():LibraryGlyphCatalogue.isGlyphQuest(quest)&&supported())||!TreeQuestService.real(p))return false;var store=CommerceService.store(p.server);var r=store.professions(p.getUUID());return !store.quarantined()&&r.isActive(Profession.LIBRARIAN)&&r.progressBand(Profession.LIBRARIAN)==ApprovedProfessionContent.get(quest).rank()&&!r.track(Profession.LIBRARIAN).completedQuestIds().contains(quest)&&LibraryGlyphCatalogue.catalog().mayAttempt(Profession.LIBRARIAN,quest,r.track(Profession.LIBRARIAN).completedQuestIds())&&com.mohymods.kingdomsmp.contribution.ContributionService.kingdom(p.server).attainedTier()>=com.mohymods.kingdomsmp.kingdom.AlphaScope.questTier(quest)&&ProfessionService.available(p,Profession.LIBRARIAN);}
 private static boolean nativeGlyph(ServerPlayer p,ItemStack stack){if(stack.isEmpty()||!LibraryGlyphCatalogue.glyph(net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(stack.getItem()).toString()))return false;try{
  var glyph=Class.forName("com.hollingsworth.arsnouveau.common.items.Glyph");if(!glyph.isInstance(stack.getItem()))return false;var spell=glyph.getField("spellPart").get(stack.getItem());var part=Class.forName("com.hollingsworth.arsnouveau.api.spell.AbstractSpellPart");var tier=part.getMethod("getConfigTier").invoke(spell);return tier.getClass().getField("value").getInt(tier)==2&&(Boolean)part.getMethod("isEnabled").invoke(spell)&&p.server.getRecipeManager().getRecipes().stream().anyMatch(r->r.value().getResultItem(p.registryAccess()).is(stack.getItem()));
 }catch(ReflectiveOperationException|RuntimeException unavailable){return false;}}
 private static String scan(ServerPlayer admin,ServerPlayer p,String quest)throws IOException{
  if(!admin.hasPermissions(2)||admin instanceof net.neoforged.neoforge.common.util.FakePlayer||!admin.isAlive()||admin.server.getPlayerList().getPlayer(admin.getUUID())!=admin||p.server.getPlayerList().getPlayer(p.getUUID())!=p||!eligible(p,quest)||admin.serverLevel()!=p.serverLevel()||admin.distanceToSqr(p)>256)throw new IllegalStateException("A living on-site OP2 and eligible survival Librarian must attend the Tier 6 Library");
  if(p.containerMenu!=p.inventoryMenu||!p.inventoryMenu.getCarried().isEmpty())throw new IllegalStateException("Close containers before catalogue delivery");var store=CommerceService.store(p.server);if(store.pendingItem().isPresent()||store.pendingSale().isPresent()||store.pendingTransfer().isPresent())throw new IllegalStateException("Resolve pending native inventory recovery first");CommerceService.verifyReceipt(p,store);CommerceService.requireResidentCounter(p);var project=CommerceService.counterProject(p);if(project==null||!project.blueprint().toString().equals(Profession.LIBRARIAN.buildingId())||!ConstructionService.loaded(p.serverLevel(),project)||!ConstructionService.structureIntact(p.serverLevel(),project))throw new IllegalStateException("Visit the maintained original Library resident and loaded footprint");
  var blueprint=BlueprintRegistry.get(project.blueprint(),project.blueprintVersion());var from=new net.minecraft.core.BlockPos(project.origin().getX(),Math.max(p.serverLevel().getMinBuildHeight(),project.origin().getY()-4),project.origin().getZ());var to=new net.minecraft.core.BlockPos(project.origin().getX()+blueprint.width(project.rotation())-1,Math.min(p.serverLevel().getMaxBuildHeight()-1,project.origin().getY()+blueprint.height()),project.origin().getZ()+blueprint.depth(project.rotation())-1);if(PlacementProtection.check(p.serverLevel(),p,from,to)!=null)throw new IllegalStateException("Current independent site permissions deny this player's catalogue inspection");long hash=0xcbf29ce484222325L;for(var cell:ConstructionFoundations.blocks(project)){var at=project.origin().offset(cell.offset());hash=(hash^at.asLong())*0x100000001b3L;hash=(hash^Block.getId(p.serverLevel().getBlockState(at)))*0x100000001b3L;}return project.id()+"/"+p.serverLevel().dimension().location()+"/"+Long.toUnsignedString(hash);
 }
 public static UUID review(ServerPlayer admin,ServerPlayer p,String reason)throws IOException{return review(admin,p,LibraryGlyphCatalogue.QUEST,reason);}
 public static UUID review(ServerPlayer admin,ServerPlayer p,String quest,String reason)throws IOException{
  if(reason==null||reason.isBlank()||reason.length()>128)throw new IllegalArgumentException("Record a source/research inspection reason of 1..128 characters");String snapshot=scan(admin,p,quest);var before=new ArrayList<ItemStack>();for(int i=0;i<36;i++)before.add(p.getInventory().getItem(i).copy());var after=before.stream().map(ItemStack::copy).collect(java.util.stream.Collectors.toCollection(ArrayList::new));var items=new ArrayList<CompoundTag>();var facts=new ArrayList<CompoundTag>();var seen=new HashSet<String>();
  for(int i=0;i<36&&items.size()<LibraryGlyphCatalogue.count(quest);i++){var item=before.get(i);var fact=LibrarySpellCatalogue.isSpellQuest(quest)?NativeLibraryScroll.inspect(p,item):null;String definition=fact!=null?fact.spell():LibraryGlyphCatalogue.isGlyphQuest(quest)&&nativeGlyph(p,item)?net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(item.getItem()).toString():null;if(definition==null||!seen.add(definition))continue;if(fact!=null)facts.add(fact.save());var one=item.copyWithCount(1);items.add((CompoundTag)one.save(p.registryAccess()));after.get(i).shrink(1);}if(LibrarySpellCatalogue.isSpellQuest(quest))LibrarySpellCatalogue.validate(quest,items,facts);else LibraryGlyphCatalogue.validate(quest,items);var q=new Quote(UUID.randomUUID(),p.getUUID(),quest,CommerceService.store(p.server).revision(),System.nanoTime(),snapshot,reason,before,after,items,facts);REVIEWS.put(admin,q);p.sendSystemMessage(Component.literal("Royal catalogue review: "+LibraryGlyphCatalogue.count(quest)+" items will be permanently consumed for "+LibraryGlyphCatalogue.xp(quest)+" XP after operator confirmation. Keep this resident interface open to proceed; close it to cancel. Definitions: "+String.join(", ",new TreeSet<>(seen))));return q.nonce();
 }
 public static void confirm(ServerPlayer admin,UUID nonce)throws IOException{confirm(admin,nonce,null);}
 private static void confirm(ServerPlayer admin,UUID nonce,String expectedQuest)throws IOException{
  var q=REVIEWS.remove(admin);if(q==null||expectedQuest!=null&&!expectedQuest.equals(q.quest())||!q.nonce().equals(nonce)||System.nanoTime()-q.issued()>30_000_000_000L)throw new IllegalStateException("Catalogue inspection expired; review again");var p=admin.server.getPlayerList().getPlayer(q.player());if(p==null)throw new IllegalStateException("Player left the inspection");var store=CommerceService.store(p.server);if(q.revision()!=store.revision()||!q.snapshot().equals(scan(admin,p,q.quest())))throw new IllegalStateException("Catalogue geometry, permissions or records changed");for(int i=0;i<36;i++)if(!ItemStack.matches(p.getInventory().getItem(i),q.before().get(i)))throw new IllegalStateException("Inventory changed; review again");for(int i=0;i<q.items().size();i++){var item=ItemStack.parse(p.registryAccess(),q.items().get(i)).orElseThrow();if(LibrarySpellCatalogue.isSpellQuest(q.quest())){var fact=NativeLibraryScroll.inspect(p,item);if(fact==null||!fact.save().equals(q.facts().get(i)))throw new IllegalStateException("Native spell rarity, availability or configuration changed");}else if(!nativeGlyph(p,item))throw new IllegalStateException("Native glyph tier/recipe/configuration changed");}
  var old=p.getPersistentData().copy();boolean saving=false;try{CommerceService.checkpoint(p);var pending=store.prepareLibraryCatalogue(q.nonce(),p.getUUID(),admin.getUUID(),q.quest(),q.items(),q.facts(),q.snapshot()+" | "+q.reason());for(int i=0;i<36;i++)p.getInventory().setItem(i,q.after().get(i).copy());CommerceService.putReceipt(p,new EconomyStore.Receipt(store.id(),pending.sequence()));saving=true;CommerceService.checkpoint(p);if(!store.recoverItem(CommerceService.receipt(AtomicNbt.read(CommerceService.playerFile(p.server,p.getUUID())))))throw new IOException("Catalogue native receipt did not commit");p.getInventory().setChanged();p.inventoryMenu.sendAllDataToRemote();admin.sendSystemMessage(Component.literal(LibraryGlyphCatalogue.count(q.quest())+" inspected native catalogue items delivered; "+LibraryGlyphCatalogue.xp(q.quest())+" Librarian XP recorded once."));p.sendSystemMessage(Component.literal("Research catalogue recorded. "+LibraryGlyphCatalogue.count(q.quest())+" items consumed; "+LibraryGlyphCatalogue.xp(q.quest())+" XP earned."));}
  catch(IOException|RuntimeException failure){if(!saving){for(int i=0;i<36;i++)p.getInventory().setItem(i,q.before().get(i).copy());for(var key:new HashSet<>(p.getPersistentData().getAllKeys()))p.getPersistentData().remove(key);p.getPersistentData().merge(old);}if(!saving&&store.pendingItem().isEmpty()&&!store.quarantined()&&(failure instanceof IllegalStateException||failure instanceof IllegalArgumentException))throw failure;store.quarantine();p.connection.disconnect(Component.literal("Catalogue delivery interrupted; restore matching native and canonical checkpoints"));throw failure;}
 }
 public static com.mojang.brigadier.builder.LiteralArgumentBuilder<CommandSourceStack> commands(){return commands(LibraryGlyphCatalogue.QUEST,"glyph_catalogue");}
 public static com.mojang.brigadier.builder.LiteralArgumentBuilder<CommandSourceStack> spellCommands(){return commands(LibrarySpellCatalogue.QUEST,"spell_catalogue");}
 public static com.mojang.brigadier.builder.LiteralArgumentBuilder<CommandSourceStack> masterGlyphCommands(){return commands(LibraryGlyphCatalogue.MASTER,"master_glyph_archive");}
 public static com.mojang.brigadier.builder.LiteralArgumentBuilder<CommandSourceStack> masterSpellCommands(){return commands(LibrarySpellCatalogue.MASTER,"master_spell_archive");}
 private static com.mojang.brigadier.builder.LiteralArgumentBuilder<CommandSourceStack> commands(String quest,String label){return Commands.literal(label).requires(s->s.hasPermission(2))
  .then(Commands.literal("confirm").then(Commands.argument("nonce",UuidArgument.uuid()).executes(c->{try{confirm(c.getSource().getPlayerOrException(),UuidArgument.getUuid(c,"nonce"),quest);return 1;}catch(IOException|IllegalStateException|IllegalArgumentException e){c.getSource().sendFailure(Component.literal(e.getMessage()));return 0;}})))
  .then(Commands.argument("player",EntityArgument.player()).then(Commands.argument("reason",StringArgumentType.greedyString()).executes(c->{try{var admin=c.getSource().getPlayerOrException();var p=EntityArgument.getPlayer(c,"player");var nonce=review(admin,p,quest,StringArgumentType.getString(c,"reason"));admin.sendSystemMessage(Component.literal("Review: permanently consume "+LibraryGlyphCatalogue.count(quest)+" different inspected definitions for "+LibraryGlyphCatalogue.xp(quest)+" XP. ").append(Component.literal("[CONFIRM CATALOGUE]").withStyle(s->s.withColor(net.minecraft.ChatFormatting.GOLD).withClickEvent(new ClickEvent(ClickEvent.Action.RUN_COMMAND,"/kingdom admin profession "+label+" confirm "+nonce)))));return 1;}catch(IOException|IllegalArgumentException|IllegalStateException e){c.getSource().sendFailure(Component.literal(e.getMessage()));return 0;}})));}
}
